function adminUrl(string $section,array $params=[]): string {return 'index.php?'.http_build_query(array_merge(['section'=>$section],$params));}
function adminPager(string $section,int $page,int $pages,array $params=[]): void {$total=(int)($GLOBALS['total']??0);$limit=(int)($_GET['per_page']??10);$start=$total?($page-1)*$limit+1:0;$end=min($page*$limit,$total);$params['per_page']=$limit;?><div class="resource-footer"><span>Hiển thị <?=$start?>–<?=$end?> trong tổng số <?=number_format($total)?> kết quả</span><label>Mỗi trang <select aria-label="Số dòng mỗi trang" onchange="const u=new URL(location.href);u.searchParams.set('per_page',this.value);u.searchParams.delete('page_no');location.href=u"><?php foreach([10,25,50] as $n):?><option value="<?=$n?>" <?=$limit===$n?'selected':''?>><?=$n?></option><?php endforeach;?></select></label><nav class="admin-pagination" aria-label="Chuyển trang"><?php if($pages>1):for($i=1;$i<=$pages;$i++):$params['page_no']=$i;?><a class="<?=$i===$page?'current':''?>" href="<?=e(adminUrl($section,$params))?>"><?=$i?></a><?php endfor;endif;?></nav></div><?php }
function smoothChartPath(array $points): string {
    $count=count($points);if($count===0)return '';
    $fmt=static fn(float $value):string=>number_format($value,2,'.','');
    $path='M '.$fmt((float)$points[0]['x']).' '.$fmt((float)$points[0]['y']);
    for($i=0;$i<$count-1;$i++){
        $p0=$points[max(0,$i-1)];$p1=$points[$i];$p2=$points[$i+1];$p3=$points[min($count-1,$i+2)];
        $c1x=(float)$p1['x']+((float)$p2['x']-(float)$p0['x'])/6;$c1y=(float)$p1['y']+((float)$p2['y']-(float)$p0['y'])/6;
        $c2x=(float)$p2['x']-((float)$p3['x']-(float)$p1['x'])/6;$c2y=(float)$p2['y']-((float)$p3['y']-(float)$p1['y'])/6;
        // Giữ các tay điều khiển trong khoảng hai điểm để đường cong không vượt
        // xuống dưới 0 hoặc nhô quá cao khi số liệu có nhiều điểm bằng nhau.
        $minY=min((float)$p1['y'],(float)$p2['y']);$maxY=max((float)$p1['y'],(float)$p2['y']);
        $c1y=max($minY,min($maxY,$c1y));$c2y=max($minY,min($maxY,$c2y));
        $path.=' C '.$fmt($c1x).' '.$fmt($c1y).' '.$fmt($c2x).' '.$fmt($c2y).' '.$fmt((float)$p2['x']).' '.$fmt((float)$p2['y']);
    }
    return $path;
}
$sectionNames=['dashboard'=>'Tổng quan','products'=>'Sản phẩm','categories'=>'Danh mục','brands'=>'Thương hiệu','orders'=>'Đơn hàng','customers'=>'Khách hàng','reviews'=>'Đánh giá','contacts'=>'Liên hệ','staff'=>'Nhân viên','attendance'=>'Chấm công'];$sectionIcons=['dashboard'=>'◫','products'=>'▦','categories'=>'▤','brands'=>'◇','orders'=>'▣','customers'=>'♙','reviews'=>'☆','contacts'=>'✉','staff'=>'♙','attendance'=>'◷'];$pageTitle=$sectionNames[$section]??'Tổng quan';$adminName=user()['name']??'Quản trị viên';
if($section==='dashboard'){
    $chartW=900;$chartH=290;$chartLeft=72;$chartRight=18;$chartTop=18;$chartBottom=44;$plotW=$chartW-$chartLeft-$chartRight;$plotH=$chartH-$chartTop-$chartBottom;$seriesCount=max(1,count($chartSeries));$chartRevenueTotal=array_sum(array_column($chartSeries,'revenue'));$chartOrdersTotal=array_sum(array_column($chartSeries,'orders'));
    $revenueValues=array_merge(array_column($chartSeries,'revenue'),array_column($chartSeries,'previous_revenue'));$revenueMax=max(0,(float)max($revenueValues));$revenueAxis=max(1000000000,ceil($revenueMax/4)*4);
    $orderValues=array_merge(array_column($chartSeries,'orders'),array_column($chartSeries,'previous_orders'));$ordersAxis=max(4,ceil(max($orderValues)/4)*4);$revenuePoints=[];$previousRevenuePoints=[];$ordersBars=[];$previousOrderPoints=[];
    foreach($chartSeries as $i=>$point){$x=$chartLeft+($seriesCount>1?$i*$plotW/($seriesCount-1):$plotW/2);$y=$chartTop+$plotH-($point['revenue']/$revenueAxis*$plotH);$previousY=$chartTop+$plotH-($point['previous_revenue']/$revenueAxis*$plotH);$revenuePoints[]=['x'=>$x,'y'=>$y,'label'=>$point['label'],'value'=>$point['revenue']];$previousRevenuePoints[]=['x'=>$x,'y'=>$previousY];$prevOrderY=$chartTop+$plotH-($point['previous_orders']/$ordersAxis*$plotH);$previousOrderPoints[]=['x'=>$x,'y'=>$prevOrderY];$slot=$plotW/$seriesCount;$barW=max(3,$slot*.58);$barX=$chartLeft+$i*$slot+($slot-$barW)/2;$barH=$point['orders']/$ordersAxis*$plotH;$ordersBars[]=['x'=>$barX,'y'=>$chartTop+$plotH-$barH,'w'=>$barW,'h'=>$barH,'label'=>$point['label'],'value'=>$point['orders']];}
    $revenuePath=smoothChartPath($revenuePoints);$previousRevenuePath=smoothChartPath($previousRevenuePoints);$areaPath=$revenuePath.' L '.number_format($revenuePoints[count($revenuePoints)-1]['x'],2,'.',' ').' '.($chartTop+$plotH).' L '.number_format($revenuePoints[0]['x'],2,'.',' ').' '.($chartTop+$plotH).' Z';
    $previousOrdersPath=smoothChartPath($previousOrderPoints);
    $customerMax=max(0,(int)max(array_column($customerSeries,'customers')));$customerAxis=max(4,ceil($customerMax/4)*4);$customerPoints=[];foreach($customerSeries as $i=>$point){$x=$chartLeft+($seriesCount>1?$i*$plotW/($seriesCount-1):$plotW/2);$y=$chartTop+$plotH-($point['customers']/$customerAxis*$plotH);$customerPoints[]=['x'=>$x,'y'=>$y,'label'=>$point['label'],'value'=>$point['customers']];}$customerPath=smoothChartPath($customerPoints);$customerAreaPath=$customerPath.' L '.number_format($customerPoints[count($customerPoints)-1]['x'],2,'.',' ').' '.($chartTop+$plotH).' L '.number_format($customerPoints[0]['x'],2,'.',' ').' '.($chartTop+$plotH).' Z';
}?>
