<?php else:$baseSeconds=max(0,$attendanceTotalSeconds-(int)($openShift?max(0,time()-strtotime($openShift['started_at'])):0));?><div class="admin-page-heading"><div><span class="admin-eyebrow">CA LÀM CỦA BẠN</span><h1>Chấm công</h1><p>Tiền công được tính theo thời gian thực tế, mức 22.000đ cho mỗi giờ làm.</p></div></div><section class="stat-grid analytics-stats attendance-summary"><article class="stat-card"><div class="stat-top"><span>Tổng giờ đã làm</span><i>◷</i></div><strong data-attendance-hours><?=number_format($attendanceTotalHours,2,',','.')?> giờ</strong></article><article class="stat-card"><div class="stat-top"><span>Tiền công tạm tính</span><i>₫</i></div><strong class="stat-money" data-attendance-pay><?=money($attendanceTotalPay)?></strong><small>22.000đ/giờ · Chưa trừ các khoản khác</small></article><article class="stat-card"><div class="stat-top"><span>Trạng thái ca</span><i><?=($openShift?'●':'○')?></i></div><strong><?=($openShift?'Đang làm':'Chưa bắt đầu')?></strong><?php if($openShift):?><small>Bắt đầu lúc <?=e(date('d/m/Y H:i',strtotime($openShift['started_at'])))?></small><?php endif;?></article></section><section class="admin-panel attendance-clock-panel"><div><span class="admin-eyebrow">CHẤM CÔNG</span><h2><?=$openShift?'Ca làm đang diễn ra':'Sẵn sàng bắt đầu công việc?'?></h2><p><?=$openShift?'Bộ đếm thời gian sẽ cập nhật tự động khi ca đang mở.':'Bấm bắt đầu khi vào làm; nhớ kết thúc ca khi xong việc.'?></p><?php if($openShift):?><div class="attendance-live-clock" data-started-at="<?=strtotime($openShift['started_at'])?>" data-open-elapsed="<?=max(0,time()-strtotime($openShift['started_at']))?>" data-base-seconds="<?=$baseSeconds?>" data-adjustment-hours="<?=e((string)$attendanceAdjustmentHours)?>"><span>Thời gian ca này</span><strong data-shift-duration>00:00:00</strong><span>Tiền công tạm tính ca này: <b data-shift-pay>0đ</b></span></div><?php endif;?></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="section" value="attendance"><input type="hidden" name="action" value="<?=$openShift?'clock_out':'clock_in'?>"><button class="<?=$openShift?'admin-danger':'admin-primary'?> attendance-clock-button" type="submit"><?=$openShift?'■ Kết thúc công việc':'▶ Bắt đầu công việc'?></button></form></section><section class="admin-panel attendance-history-panel"><div class="panel-heading"><div><h2>Lịch sử ca làm</h2><p>Các ca được lưu trong tài khoản của bạn.</p></div></div><div class="admin-table-wrap"><table class="admin-table attendance-history-table"><thead><tr><th>NGÀY</th><th>BẮT ĐẦU</th><th>KẾT THÚC</th><th>THỜI LƯỢNG</th><th>TIỀN CÔNG</th></tr></thead><tbody><?php if(!$attendanceRows):?><tr><td colspan="5" class="empty-cell">Bạn chưa có ca làm được ghi nhận.</td></tr><?php else:foreach($attendanceRows as $shift):$shiftSeconds=max(0,(int)$shift['duration_seconds']);?><tr><td><?=e(date('d/m/Y',strtotime($shift['started_at'])))?></td><td><?=e(date('H:i',strtotime($shift['started_at'])))?></td><td><?=$shift['ended_at']?e(date('H:i',strtotime($shift['ended_at']))):'—'?></td><td><?=floor($shiftSeconds/3600)?> giờ <?=floor(($shiftSeconds%3600)/60)?> phút</td><td><b><?=money(round($shiftSeconds/3600*$hourlyWage))?></b></td></tr><?php endforeach;endif;?></tbody></table></div></section><script>(function(){const clock=document.querySelector('.attendance-live-clock');if(!clock)return;const base=Number(clock.dataset.baseSeconds)||0,elapsedAtLoad=Number(clock.dataset.openElapsed)||0,adjustment=Number(clock.dataset.adjustmentHours)||0,loadedAt=performance.now(),duration=clock.querySelector('[data-shift-duration]'),shiftPay=clock.querySelector('[data-shift-pay]'),hours=document.querySelector('[data-attendance-hours]'),pay=document.querySelector('[data-attendance-pay]');const money=value=>new Intl.NumberFormat('vi-VN').format(value)+'đ';function tick(){const live=elapsedAtLoad+Math.floor((performance.now()-loadedAt)/1000),totalHours=Math.max(0,(base+live)/3600+adjustment),h=Math.floor(live/3600),m=Math.floor(live%3600/60),s=live%60;duration.textContent=[h,m,s].map(v=>String(v).padStart(2,'0')).join(':');shiftPay.textContent=money(Math.round(live/3600*22000));if(hours)hours.textContent=totalHours.toLocaleString('vi-VN',{minimumFractionDigits:2,maximumFractionDigits:2})+' giờ';if(pay)pay.textContent=money(Math.round(totalHours*22000));}tick();window.setInterval(tick,1000)})();</script><?php endif;?>
